PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS storage_roots(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, absolute_path TEXT NOT NULL, path_key TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'available', created_at INTEGER NOT NULL, UNIQUE(owner_id,id), UNIQUE(owner_id,path_key));
CREATE TABLE IF NOT EXISTS owner_settings(owner_id TEXT PRIMARY KEY, active_root_id TEXT NOT NULL, storage_revision INTEGER NOT NULL DEFAULT 0, content_hash TEXT NOT NULL, runtime_token TEXT NOT NULL, updated_at INTEGER NOT NULL, FOREIGN KEY(owner_id,active_root_id) REFERENCES storage_roots(owner_id,id));
CREATE TABLE IF NOT EXISTS folders(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, name TEXT NOT NULL, meta_revision INTEGER NOT NULL DEFAULT 0, content_hash TEXT NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(owner_id,id), UNIQUE(owner_id,name));
CREATE TABLE IF NOT EXISTS canvases(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL, folder_id TEXT, name TEXT NOT NULL, meta_revision INTEGER NOT NULL DEFAULT 0, graph_revision INTEGER NOT NULL DEFAULT 0, layout_revision INTEGER NOT NULL DEFAULT 0, target_storage_id TEXT NOT NULL, content_hash TEXT NOT NULL, commit_hash TEXT NOT NULL, min_replay_revision INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, deleted_at INTEGER, FOREIGN KEY(owner_id,folder_id) REFERENCES folders(owner_id,id), FOREIGN KEY(id,target_storage_id) REFERENCES canvas_storage_locations(canvas_id,id) DEFERRABLE INITIALLY DEFERRED);
CREATE UNIQUE INDEX IF NOT EXISTS canvas_root_name ON canvases(owner_id,name) WHERE folder_id IS NULL AND deleted_at IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS canvas_folder_name ON canvases(owner_id,folder_id,name) WHERE folder_id IS NOT NULL AND deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS canvas_folder ON canvases(owner_id,folder_id,updated_at);
CREATE TABLE IF NOT EXISTS canvas_storage_locations(canvas_id TEXT NOT NULL, id TEXT NOT NULL, root_id TEXT NOT NULL REFERENCES storage_roots(id), relative_dir TEXT NOT NULL, directory_key TEXT NOT NULL, created_at INTEGER NOT NULL, PRIMARY KEY(canvas_id,id), UNIQUE(root_id,directory_key), FOREIGN KEY(canvas_id) REFERENCES canvases(id) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS canvas_assets(canvas_id TEXT NOT NULL REFERENCES canvases(id), id TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('image','video','audio')), origin_kind TEXT NOT NULL, original_filename TEXT, name_source_node_id TEXT, name_snapshot TEXT NOT NULL, storage_id TEXT, file_name TEXT, file_name_key TEXT, mime TEXT, bytes INTEGER, file_hash TEXT, file_state TEXT NOT NULL CHECK(file_state IN ('staging','ready','missing')), width INTEGER, height INTEGER, duration REAL, row_version INTEGER NOT NULL DEFAULT 0, content_hash TEXT NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, task_id TEXT, PRIMARY KEY(canvas_id,id), FOREIGN KEY(canvas_id,storage_id) REFERENCES canvas_storage_locations(canvas_id,id), CHECK(file_state != 'ready' OR (storage_id IS NOT NULL AND file_name IS NOT NULL AND mime IS NOT NULL AND bytes IS NOT NULL AND file_hash IS NOT NULL)));
CREATE UNIQUE INDEX IF NOT EXISTS asset_filename ON canvas_assets(canvas_id,storage_id,file_name_key) WHERE storage_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS asset_name_source ON canvas_assets(canvas_id,name_source_node_id);
CREATE INDEX IF NOT EXISTS asset_state ON canvas_assets(file_state,updated_at);
CREATE INDEX IF NOT EXISTS asset_task ON canvas_assets(task_id);
CREATE TABLE IF NOT EXISTS canvas_nodes(canvas_id TEXT NOT NULL REFERENCES canvases(id), id TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('image-generation','video-generation','image-asset','video-asset','audio-asset')), title TEXT NOT NULL, name_revision INTEGER NOT NULL DEFAULT 0, position_x REAL NOT NULL, position_y REAL NOT NULL, model_id TEXT, prompt TEXT NOT NULL, params_json TEXT CHECK(params_json IS NULL OR json_valid(params_json)), asset_id TEXT, selected_result_id TEXT, sort_order INTEGER NOT NULL, row_version INTEGER NOT NULL DEFAULT 0, content_hash TEXT NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, PRIMARY KEY(canvas_id,id), FOREIGN KEY(canvas_id,asset_id) REFERENCES canvas_assets(canvas_id,id) DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY(canvas_id,selected_result_id) REFERENCES canvas_assets(canvas_id,id) DEFERRABLE INITIALLY DEFERRED);
CREATE INDEX IF NOT EXISTS node_order ON canvas_nodes(canvas_id,sort_order);
CREATE INDEX IF NOT EXISTS node_asset ON canvas_nodes(canvas_id,asset_id);
CREATE INDEX IF NOT EXISTS node_result ON canvas_nodes(canvas_id,selected_result_id);
CREATE TABLE IF NOT EXISTS canvas_edges(canvas_id TEXT NOT NULL REFERENCES canvases(id), id TEXT NOT NULL, asset_id TEXT NOT NULL, sort_order INTEGER NOT NULL, row_version INTEGER NOT NULL DEFAULT 0, content_hash TEXT NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, PRIMARY KEY(canvas_id,id), FOREIGN KEY(canvas_id,asset_id) REFERENCES canvas_assets(canvas_id,id));
CREATE INDEX IF NOT EXISTS edge_order ON canvas_edges(canvas_id,sort_order);
CREATE INDEX IF NOT EXISTS edge_asset ON canvas_edges(canvas_id,asset_id);
CREATE TABLE IF NOT EXISTS edge_node_relations(canvas_id TEXT NOT NULL, edge_id TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('source','target')), node_id TEXT NOT NULL, port_key TEXT NOT NULL DEFAULT '', content_hash TEXT NOT NULL, PRIMARY KEY(canvas_id,edge_id,role), FOREIGN KEY(canvas_id,edge_id) REFERENCES canvas_edges(canvas_id,id) ON DELETE CASCADE, FOREIGN KEY(canvas_id,node_id) REFERENCES canvas_nodes(canvas_id,id));
CREATE INDEX IF NOT EXISTS relation_node ON edge_node_relations(canvas_id,node_id,role);
CREATE TABLE IF NOT EXISTS canvas_state(canvas_id TEXT PRIMARY KEY REFERENCES canvases(id), viewport_x REAL NOT NULL, viewport_y REAL NOT NULL, viewport_zoom REAL NOT NULL CHECK(viewport_zoom BETWEEN 0.05 AND 4), row_version INTEGER NOT NULL DEFAULT 0, content_hash TEXT NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS canvas_mutations(canvas_id TEXT NOT NULL REFERENCES canvases(id), mutation_id TEXT NOT NULL, actor TEXT NOT NULL, request_hash TEXT NOT NULL, base_revision INTEGER NOT NULL, committed_revision INTEGER NOT NULL, has_changes INTEGER NOT NULL, prev_commit_hash TEXT NOT NULL, commit_hash TEXT NOT NULL, changes_json TEXT NOT NULL CHECK(json_valid(changes_json)), created_at INTEGER NOT NULL, PRIMARY KEY(canvas_id,mutation_id));
CREATE UNIQUE INDEX IF NOT EXISTS mutation_revision ON canvas_mutations(canvas_id,committed_revision) WHERE has_changes=1;
CREATE INDEX IF NOT EXISTS mutation_time ON canvas_mutations(created_at);
CREATE TABLE IF NOT EXISTS catalog_mutations(owner_id TEXT NOT NULL, request_id TEXT NOT NULL, operation TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, request_hash TEXT NOT NULL, result_json TEXT NOT NULL CHECK(json_valid(result_json)), created_at INTEGER NOT NULL, PRIMARY KEY(owner_id,request_id));
CREATE INDEX IF NOT EXISTS catalog_receipt_time ON catalog_mutations(created_at);
CREATE TABLE IF NOT EXISTS task_catalog(id TEXT PRIMARY KEY, canvas_id TEXT NOT NULL REFERENCES canvases(id), node_id TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('generation','import')), title TEXT NOT NULL, queue_seq INTEGER NOT NULL UNIQUE, status TEXT NOT NULL CHECK(status IN ('queued','running','external_wait','saving','succeeded','failed','needs_attention','save_failed','abandoned')), progress REAL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, finished_at INTEGER);
CREATE UNIQUE INDEX IF NOT EXISTS task_active_node ON task_catalog(canvas_id,node_id) WHERE status IN ('queued','running','external_wait','saving','needs_attention','save_failed');
CREATE INDEX IF NOT EXISTS task_canvas_page ON task_catalog(canvas_id,queue_seq);
CREATE INDEX IF NOT EXISTS task_due_status ON task_catalog(status,queue_seq);
CREATE INDEX IF NOT EXISTS task_node_history ON task_catalog(canvas_id,node_id,queue_seq);
CREATE TABLE IF NOT EXISTS task_details(task_id TEXT PRIMARY KEY REFERENCES task_catalog(id), request_id TEXT NOT NULL UNIQUE, request_hash TEXT NOT NULL, snapshot_json TEXT CHECK(snapshot_json IS NULL OR json_valid(snapshot_json)), credential_ref TEXT, phase TEXT NOT NULL, next_run_at INTEGER NOT NULL DEFAULT 0, lease_owner TEXT, lease_until INTEGER, submit_issued INTEGER NOT NULL DEFAULT 0, external_task_id TEXT, external_status TEXT, external_completed_at INTEGER, success_at INTEGER, failure_stage TEXT, failure_code TEXT, failure_message TEXT, outputs_json TEXT CHECK(outputs_json IS NULL OR json_valid(outputs_json)), import_json TEXT CHECK(import_json IS NULL OR json_valid(import_json)), updated_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS detail_due ON task_details(next_run_at,task_id);
CREATE INDEX IF NOT EXISTS detail_lease ON task_details(lease_until) WHERE lease_owner IS NOT NULL;
CREATE INDEX IF NOT EXISTS detail_external ON task_details(external_task_id) WHERE external_task_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS detail_credential ON task_details(credential_ref) WHERE credential_ref IS NOT NULL;
CREATE TABLE IF NOT EXISTS task_attempts(id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES task_catalog(id), step TEXT NOT NULL, issued_at INTEGER NOT NULL, finished_at INTEGER, outcome TEXT, error TEXT);
CREATE INDEX IF NOT EXISTS attempt_task ON task_attempts(task_id,issued_at);
CREATE TABLE IF NOT EXISTS task_references(task_id TEXT NOT NULL REFERENCES task_catalog(id), ordinal INTEGER NOT NULL, canvas_id TEXT NOT NULL, asset_id TEXT NOT NULL, file_hash TEXT NOT NULL, PRIMARY KEY(task_id,ordinal), FOREIGN KEY(canvas_id,asset_id) REFERENCES canvas_assets(canvas_id,id));
CREATE INDEX IF NOT EXISTS reference_asset ON task_references(canvas_id,asset_id);
CREATE TABLE IF NOT EXISTS task_outputs(task_id TEXT NOT NULL REFERENCES task_catalog(id), ordinal INTEGER NOT NULL, canvas_id TEXT NOT NULL, asset_id TEXT NOT NULL, PRIMARY KEY(task_id,ordinal), UNIQUE(task_id,asset_id), FOREIGN KEY(canvas_id,asset_id) REFERENCES canvas_assets(canvas_id,id));
CREATE INDEX IF NOT EXISTS output_asset ON task_outputs(canvas_id,asset_id);
CREATE TABLE IF NOT EXISTS upload_sessions(id TEXT PRIMARY KEY, canvas_id TEXT NOT NULL REFERENCES canvases(id), node_id TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('receiving','received','failed')), stage_file TEXT NOT NULL, bytes INTEGER NOT NULL DEFAULT 0, file_hash TEXT, task_id TEXT REFERENCES task_catalog(id), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS upload_state ON upload_sessions(state,updated_at);
CREATE INDEX IF NOT EXISTS upload_node ON upload_sessions(canvas_id,node_id);
CREATE TABLE IF NOT EXISTS file_operations(id TEXT PRIMARY KEY, canvas_id TEXT NOT NULL REFERENCES canvases(id), layout_revision INTEGER NOT NULL, state TEXT NOT NULL CHECK(state IN ('pending','running','completed','failed')), error TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS fileop_pending ON file_operations(state,created_at);
CREATE INDEX IF NOT EXISTS fileop_canvas ON file_operations(canvas_id,state);
CREATE TABLE IF NOT EXISTS file_operation_items(id TEXT PRIMARY KEY, operation_id TEXT NOT NULL REFERENCES file_operations(id), canvas_id TEXT NOT NULL, asset_id TEXT NOT NULL, source_path TEXT NOT NULL, target_storage_id TEXT NOT NULL, target_name TEXT NOT NULL, expected_hash TEXT NOT NULL, source_version INTEGER NOT NULL, state TEXT NOT NULL CHECK(state IN ('pending','copied','completed','failed','superseded')), error TEXT, updated_at INTEGER NOT NULL, FOREIGN KEY(canvas_id,asset_id) REFERENCES canvas_assets(canvas_id,id), FOREIGN KEY(canvas_id,target_storage_id) REFERENCES canvas_storage_locations(canvas_id,id));
CREATE INDEX IF NOT EXISTS fileitem_operation ON file_operation_items(operation_id,state);
CREATE INDEX IF NOT EXISTS fileitem_asset ON file_operation_items(canvas_id,asset_id,state);
CREATE TABLE IF NOT EXISTS migration_imports(source_path TEXT PRIMARY KEY, source_hash TEXT NOT NULL, canvas_id TEXT NOT NULL REFERENCES canvases(id), checkpoint TEXT NOT NULL, imported_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS migration_canvas ON migration_imports(canvas_id);
CREATE INDEX IF NOT EXISTS canvas_active_listing ON canvases(owner_id,created_at) WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS storage_canvas_root ON canvas_storage_locations(canvas_id,root_id);
CREATE INDEX IF NOT EXISTS asset_canvas_ready ON canvas_assets(canvas_id,file_state,created_at);
CREATE INDEX IF NOT EXISTS task_canvas_status ON task_catalog(canvas_id,status,queue_seq);
CREATE INDEX IF NOT EXISTS upload_task ON upload_sessions(task_id) WHERE task_id IS NOT NULL;
PRAGMA user_version=2;
